mapper.update:
update goods_spu
set status = #{toStatus}
where address = #{address}
  and status = #{fromStatus}

update goods_spu
set sales = sales + #{num}
where goods_id = #{goodsId}
  and total >= sales + #{num}

update goods_spu
set sales = sales - #{num}
where goods_id = #{goodsId}

update goods_spu
set favorite = favorite + 1
where goods_id = #{goodsId}

update goods_spu
set favorite = favorite - 1
where goods_id = #{goodsId}

mapper.select:
select * from goods_spu where `status` in
#{status}
order by goods_id limit 50

select *

    ,(
    ln(1 + sales)
    + ln(1 + favorite) * 0.2
    + IF (recommend = 1, 100, 0)
    + 3 / (1 + IF(sale_time > #{nowTimestamp}, 0, (#{nowTimestamp} - sale_time) / 604800000))
    ) as score

from goods_spu


        and address = #{address}


        and `status` = #{status}


        and hidden_status = #{hiddenStatus}


        and recommend = #{recommend}


        and JSON_CONTAINS(menu_json -> '$[*]', JSON_ARRAY(#{menuId}), '$')


        and (
        goods_id = #{vague}
        or address = #{vague}
        or `name` like CONCAT('%', #{vague}, '%')
        )



    order by goods_id desc


    order by score desc, show_order asc, sale_time desc, goods_id desc


    order by sales asc, sale_time desc, goods_id desc


    order by sales desc, sale_time desc, goods_id desc


    order by price asc, sale_time desc, goods_id desc


    order by price desc, sale_time desc, goods_id desc


    order by sale_time asc, goods_id desc


    order by sale_time desc, goods_id desc
